// Site data, loaded at build time.
// Providers come from Supabase (approved rows) when PUBLIC_SUPABASE_URL / PUBLIC_SUPABASE_ANON_KEY are set,
// otherwise from src/data/providers.json (generated by scripts/build_data.py).
// Logos: set providers.logo_url, OR upload <slug>.png / .jpg / .webp / .svg to the public "logos" storage bucket,
// OR drop the same file in public/logos/. Then redeploy.
import fs from 'node:fs';
import path from 'node:path';
import providersJson from '../data/providers.json';
import lendersJson from '../data/lenders.json';
import invertersJson from '../data/inverters.json';

export type Provider = {
  slug: string; kind: 'company' | 'installer' | 'supplier'; name: string; businessType: string;
  tagline: string; tags: string[]; servicesRaw: string; city: string; parishHq: string | null;
  parishes: string[]; address: string; website: string; phone: string; email: string;
  batteryStorage: boolean; sponsored: boolean; verified: boolean; checked: string;
  sources: string[]; notes: string; logo?: string;
};

const SUPA_URL = (import.meta.env.PUBLIC_SUPABASE_URL ?? '').replace(/\/$/, '');
const SUPA_KEY = import.meta.env.PUBLIC_SUPABASE_ANON_KEY ?? '';
const LOGO_EXT = ['png', 'jpg', 'webp', 'svg'];

async function fromSupabase(): Promise<Provider[] | null> {
  if (!SUPA_URL || !SUPA_KEY) return null;
  try {
    const r = await fetch(`${SUPA_URL}/rest/v1/providers?select=*&status=eq.approved`, { headers: { apikey: SUPA_KEY, Authorization: `Bearer ${SUPA_KEY}` }, signal: AbortSignal.timeout(15000) });
    if (!r.ok) { console.warn('[data] Supabase providers fetch failed:', r.status); return null; }
    const rows: any[] = await r.json();
    if (!rows.length) return null;
    return rows.map(x => ({
      slug: x.slug, kind: x.kind, name: x.name, businessType: x.business_type ?? '', tagline: x.tagline ?? '',
      tags: x.tags ?? [], servicesRaw: (x.tags ?? []).join('; '), city: x.city ?? '', parishHq: x.parish_hq ?? null,
      parishes: x.parishes ?? [], address: x.address ?? '', website: x.website ?? '', phone: x.phone ?? '', email: x.email ?? '',
      batteryStorage: !!x.battery_storage, sponsored: !!x.sponsored, verified: !!x.verified, checked: x.checked_date ?? '',
      sources: x.sources ?? [], notes: '', logo: x.logo_url || undefined,
    }));
  } catch (e) { console.warn('[data] Supabase unreachable, using JSON:', (e as Error).message); return null; }
}

async function findLogo(slug: string): Promise<string | undefined> {
  // 1. local file in public/logos/
  for (const ext of LOGO_EXT) {
    if (fs.existsSync(path.join(process.cwd(), 'public', 'logos', `${slug}.${ext}`))) return `/logos/${slug}.${ext}`;
  }
  // 2. Supabase storage bucket "logos"
  if (!SUPA_URL) return undefined;
  for (const ext of LOGO_EXT) {
    const url = `${SUPA_URL}/storage/v1/object/public/logos/${slug}.${ext}`;
    try { const r = await fetch(url, { method: 'HEAD', signal: AbortSignal.timeout(5000) }); if (r.ok) return url; } catch { return undefined; }
  }
  return undefined;
}

const loaded = (await fromSupabase()) ?? (providersJson as Provider[]);
export const providers: Provider[] = await Promise.all(loaded.map(async p => ({ ...p, logo: p.logo || await findLogo(p.slug) })));

export const PARISHES = ['Kingston', 'St. Andrew', 'St. Thomas', 'Portland', 'St. Mary', 'St. Ann', 'Trelawny',
  'St. James', 'Hanover', 'Westmoreland', 'St. Elizabeth', 'Manchester', 'Clarendon', 'St. Catherine'];

export const SERVICES = ['Solar PV', 'Battery Storage', 'Water Heaters', 'Maintenance', 'Off-grid', 'Commercial'];

export const DATA_AS_OF = '15 October 2026';

export const byKind = (k: Provider['kind']) =>
  providers.filter(p => p.kind === k).sort((a, b) => Number(b.sponsored) - Number(a.sponsored) || a.name.localeCompare(b.name));

export const initials = (name: string) =>
  name.replace(/\(.*?\)/g, '').split(/[\s/&-]+/).filter(w => /^[A-Za-z]/.test(w) && !['and', 'of', 'the', 'ltd', 'limited'].includes(w.toLowerCase()))
    .slice(0, 2).map(w => w[0].toUpperCase()).join('');

export const areaLabel = (p: Provider) =>
  p.parishes.length ? p.parishes.join(', ') : (p.city ? `${p.city} (parish not yet confirmed)` : 'Service area not yet confirmed');

export const hostOf = (url: string) => { try { return new URL(url).host.replace(/^www\./, ''); } catch { return url; } };

export type Lender = Record<string, string | number>;
export const lenders = lendersJson as Lender[];

export type Inverter = { brand: string; model: string; key: string; kw: number | null; output: string; voltage: string;
  size: string; hybrid: boolean; report: string; status: string; date: string; issue: string };
export const inverters = invertersJson as Inverter[];

